window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[273]={"id":"273","numero":273,"titre":"Dysphagie","objectifs":[{"id":"273-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la dysphagie","contenu":"<p>La <span class=\"kw-def\">dysphagie</span> est définie comme une <span class=\"kw-def\">sensation de gêne ou d'obstacle à la progression du bol alimentaire</span>, survenant <strong>au cours de la déglutition</strong>. C'est cette notion de blocage du transit alimentaire qui la définit.</p>\n      <p>Rappel — la <span class=\"kw-def\">déglutition</span> est le mécanisme qui comprend la <span class=\"kw-clinique\">préhension des aliments</span>, leur <span class=\"kw-clinique\">préparation dans la bouche</span>, leur <span class=\"kw-clinique\">propulsion de la bouche vers l'estomac</span>, ainsi que la <span class=\"kw-clinique\">protection des voies respiratoires</span>.</p>\n      <p><strong>Diagnostics différentiels</strong> — plusieurs symptômes sont à distinguer de la vraie <span class=\"kw-clinique\">dysphagie</span>, car aucun ne comporte de blocage alimentaire :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Odynophagie</span></td><td><span class=\"kw-clinique\">Douleur</span> ressentie lors de la progression des aliments dans l'œsophage, <span class=\"kw-alerte\">sans sensation de blocage</span></td></tr>\n          <tr><td><span class=\"kw-def\">Globus hystericus</span></td><td>Manifestation d'angoisse se traduisant par une <span class=\"kw-clinique\">sensation de compression cervicale</span> (« gorge nouée »), majorée par le stress</td></tr>\n          <tr><td><span class=\"kw-def\">Anorexie</span></td><td><span class=\"kw-clinique\">Perte d'appétit</span> entraînant une baisse des prises alimentaires</td></tr>\n          <tr><td><span class=\"kw-def\">Satiété précoce</span></td><td>Le bol alimentaire descend normalement mais la <span class=\"kw-clinique\">faim est rapidement coupée</span></td></tr>\n          <tr><td><span class=\"kw-def\">Syndrome de rumination</span></td><td><span class=\"kw-clinique\">Remontées d'aliments</span> descendus normalement dans l'estomac, provoquées par le patient — <span class=\"kw-alerte\">pas de blocage alimentaire</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège ⚠️</strong> — l'<span class=\"kw-clinique\">odynophagie</span> (déglutition douloureuse) n'est <strong>pas</strong> une <span class=\"kw-clinique\">dysphagie</span> : c'est une douleur sans obstacle. <span class=\"kw-clinique\">Les</span> deux peuvent toutefois coexister (« dysphagie douloureuse »), orientant alors vers une infection, une œsophagite ou une tumeur.</div>","frequence":1},{"id":"273-2","rang":"A","rubrique":"Définition","titre":"Connaître les deux types de dysphagie","contenu":"<p>La <span class=\"kw-clinique\">dysphagie</span> se classe selon <strong>deux axes complémentaires</strong> : le <span class=\"kw-def\">siège</span> de la gêne et le <span class=\"kw-def\">mécanisme</span> en cause. Ces deux axes orientent l'ensemble de la démarche diagnostique.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 1 — selon la localisation</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dysphagie œsophagienne</span></td><td>Sensation de <span class=\"kw-clinique\">blocage du bol alimentaire au niveau rétrosternal</span>, après le déclenchement de la déglutition</td></tr>\n          <tr><td><span class=\"kw-def\">Dysphagie oropharyngée</span></td><td><span class=\"kw-clinique\">Difficulté à initier la déglutition</span> et à propulser le bol dans l'œsophage, gêne ressentie <span class=\"kw-clinique\">au niveau cervical</span> ; causes essentiellement <span class=\"kw-etio\">ORL</span> ou <span class=\"kw-etio\">neurologiques</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 2 — selon le mécanisme</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dysphagie lésionnelle</span></td><td>Liée à une <span class=\"kw-etio\">lésion organique œsophagienne</span> ou à une <span class=\"kw-etio\">compression extrinsèque</span></td></tr>\n          <tr><td><span class=\"kw-def\">Dysphagie fonctionnelle</span> (non lésionnelle)</td><td><span class=\"kw-alerte\">Aucune lésion identifiée</span> : anomalie de la <span class=\"kw-clinique\">dynamique propulsive</span> du bol alimentaire</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"273-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","contenu":"<p>Devant toute <span class=\"kw-clinique\">dysphagie</span>, l'interrogatoire est l'étape clé : il oriente d'emblée vers une dysphagie <span class=\"kw-def\">lésionnelle</span> ou <span class=\"kw-def\">non lésionnelle</span>, précise le siège <span class=\"kw-def\">oropharyngé</span> ou <span class=\"kw-def\">œsophagien</span>, et recherche <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span>. <strong>Objectif à haut rendement — 3 QCM EDN.</strong></p>\n      <table >\n        <thead><tr><th>Élément</th><th>Orientation diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td><span class=\"kw-etio\">Intoxication alcoolo-tabagique</span> ; antécédents personnels ; traitements en cours (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">biphosphonates</span>, <span class=\"kw-ttt\">tétracyclines</span>, <span class=\"kw-ttt\">chlorure de potassium</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td><strong>Aggravation croissante :</strong> évocatrice d'une pathologie <span class=\"kw-alerte\">tumorale</span><br><strong>Survenue brutale :</strong> <span class=\"kw-etio\">corps étranger</span><br><strong>Installation progressive :</strong> <span class=\"kw-etio\">sténose œsophagienne</span></td></tr>\n          <tr><td>Type d'aliment</td><td><strong>Prédominance sur <span class=\"kw-clinique\">les</span> solides :</strong> <span class=\"kw-clinique\">dysphagie</span> <span class=\"kw-def\">lésionnelle</span><br><strong>Prédominance sur les liquides :</strong> dysphagie <span class=\"kw-def\">non lésionnelle</span><br><strong>Dysphagie paradoxale</strong> (prédominant sur les liquides) : classique de l'<span class=\"kw-etio\">achalasie</span>, mais inconstante<br><strong>Prédominance sur les solides :</strong> aussi possible dans un défaut de propulsion pharyngée ou d'ouverture du SSO (valeur relative)</td></tr>\n          <tr><td>Stase salivaire</td><td><span class=\"kw-alerte\">Très bon signe d'organicité</span> : bon indicateur d'une <span class=\"kw-clinique\">baisse de la propulsion pharyngée</span> ou d'un <span class=\"kw-clinique\">trouble de la relaxation du SSO</span></td></tr>\n          <tr><td>Symptômes associés</td><td><strong>Dysphonie, <span class=\"kw-clinique\">dyspnée</span> :</strong> <span class=\"kw-etio\">paralysie laryngée</span> associée, obstacle laryngo-trachéal<br><strong><span class=\"kw-clinique\">Dysphagie</span> douloureuse (odynophagie) :</strong> <span class=\"kw-etio\">infection</span>, <span class=\"kw-etio\">œsophagite</span>, <span class=\"kw-etio\">tumeur</span><br><strong>Ruminations, <span class=\"kw-clinique\">régurgitations</span>, bruits hydro-aériques :</strong> <span class=\"kw-etio\">diverticule de Zenker</span><br><strong><span class=\"kw-clinique\">Otalgie</span> réflexe :</strong> doit faire <span class=\"kw-alerte\">rechercher un cancer</span> du pharynx ou du vestibule laryngé</td></tr>\n          <tr><td>Atteinte oropharyngée</td><td><strong>Temps volontaire :</strong> troubles des <span class=\"kw-clinique\">praxies buccales</span>, <span class=\"kw-clinique\">bavage</span>, <span class=\"kw-clinique\">incontinence labiale</span>, résidus alimentaires buccaux<br><strong>Temps pharyngo-laryngé :</strong> <span class=\"kw-clinique\">voix gargouillante / humide</span> (stase salivaire dans l'hypopharynx), déglutition répétée d'une même bouchée<br><strong>Défaut de protection des voies respiratoires :</strong> <span class=\"kw-alerte\">régurgitations nasales</span>, <span class=\"kw-alerte\">toux au moment des repas</span>, <span class=\"kw-alerte\">fausses routes</span> alimentaires ou salivaires<br>→ oriente vers une <span class=\"kw-clinique\">dysphagie</span> <span class=\"kw-def\">oropharyngée</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Signes de gravité</span></td><td><span class=\"kw-alerte\">Infections pulmonaires / pneumopathies à répétition</span> sur fausses routes ; <span class=\"kw-alerte\">perte de poids</span> ; <span class=\"kw-alerte\">dénutrition</span> ; <span class=\"kw-alerte\">déshydratation</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe EDN 🚩</strong> — <span class=\"kw-alerte\">toute dysphagie doit être considérée comme lésionnelle (cancer de l'œsophage) jusqu'à preuve du contraire</span>. L'<span class=\"kw-imagerie\">endoscopie</span> œsogastroduodénale avec <span class=\"kw-bio\">biopsies</span> est donc systématique.</div>","frequence":3},{"id":"273-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","contenu":"<p>L'<span class=\"kw-imagerie\">endoscopie œsogastroduodénale (EOGD)</span> est l'<strong>examen clé de <span class=\"kw-chiffre\">première intention</span> devant TOUTE <span class=\"kw-clinique\">dysphagie</span></strong>. Elle visualise directement la muqueuse œsophagienne, gastrique et duodénale et permet la réalisation de <span class=\"kw-bio\">biopsies</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Biopsies</span> systématiques</strong>, <span class=\"kw-alerte\">même si la muqueuse paraît macroscopiquement normale</span> : recherche d'une <span class=\"kw-etio\">œsophagite à éosinophiles</span>, cause classique de <span class=\"kw-clinique\">dysphagie</span> à <span class=\"kw-imagerie\">endoscopie</span> normale.</li>\n        <li>Une <span class=\"kw-clinique\">sensation de ressaut au passage de l'endoscope</span> à travers la <span class=\"kw-clinique\">jonction œsogastrique</span> est évocatrice d'un <span class=\"kw-etio\">trouble moteur œsophagien</span>.</li>\n        <li><strong>Limites :</strong> l'<span class=\"kw-imagerie\">endoscopie</span> peut être <span class=\"kw-alerte\">incomplète</span> en cas de <span class=\"kw-alerte\">sténose non franchissable</span> ou de <span class=\"kw-alerte\">stase alimentaire</span> abondante.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir</strong> — l'<span class=\"kw-imagerie\">EOGD</span> est demandée en <span class=\"kw-chiffre\">première intention</span> quel que soit le type de <span class=\"kw-clinique\">dysphagie</span> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">biopsies</span> sont indispensables, car une muqueuse macroscopiquement normale n'élimine pas une œsophagite à <span class=\"kw-bio\">éosinophiles</span>.</div>","frequence":0},{"id":"273-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires non biologiques à effectuer en deuxième intention devant une dysphagie","contenu":"<p><span class=\"kw-clinique\">Les</span> examens de seconde intention sont indiqués lorsque l'<span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-bio\">biopsies</span> est <strong>normale</strong> ou techniquement insuffisante. Ils diffèrent selon que la <span class=\"kw-clinique\">dysphagie</span> est œsophagienne ou oropharyngée.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dysphagie</span> œsophagienne</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication et apport</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Manométrie œsophagienne</span></td><td>Indiquée en 2ᵉ intention si <span class=\"kw-clinique\">dysphagie</span> inexpliquée par une <span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-bio\">biopsies</span> normales ; réalisée en ambulatoire chez un patient vigile. Évalue le <span class=\"kw-clinique\">péristaltisme œsophagien</span> (<span class=\"kw-alerte\">absent dans l'achalasie</span>) et la <span class=\"kw-clinique\">relaxation du SIO</span> (<span class=\"kw-alerte\">défaut de relaxation dans l'achalasie</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne injectée</span></td><td>Avec opacification digestive haute : recherche une <span class=\"kw-etio\">compression extrinsèque</span> — volumineuse <span class=\"kw-etio\">hernie hiatale par roulement</span>, <span class=\"kw-etio\">diverticule œsophagien</span>, <span class=\"kw-etio\">tumeur médiastinale ou pulmonaire</span>, <span class=\"kw-etio\">adénopathies</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Écho-endoscopie haute</span></td><td>En cas de suspicion de <span class=\"kw-etio\">tumeur sous-muqueuse</span> à l'<span class=\"kw-imagerie\">EOGD</span> : caractérise la <span class=\"kw-clinique\">lésion</span> et permet de la ponctionner</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TOGD</span></td><td><span class=\"kw-alerte\">Quasiment abandonné</span> : moins précis que le <span class=\"kw-imagerie\">scanner</span> avec opacification digestive</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dysphagie</span> oropharyngée</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td>Exploration de la prise alimentaire</td><td>Repas test pris devant un <span class=\"kw-clinique\">observateur</span> médical ou paramédical (diététicienne, orthophoniste, IDE, aide-soignant) ; au terme du repas, des <span class=\"kw-clinique\">adaptations de texture</span> peuvent être décidées</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Nasofibroscopie de la déglutition</span></td><td>Peu invasive ; observe le carrefour pharyngo-laryngé lors de la déglutition d'aliments de consistance variable ; diagnostic indirect des troubles (<span class=\"kw-clinique\">toux</span>, stase salivaire, résidus hypopharyngés, fausses routes secondaires)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radio-cinéma de déglutition</span> (vidéo-fluoroscopie)</td><td><span class=\"kw-alerte\">Examen de référence (gold standard)</span> : film de la déglutition après ingestion d'un produit baryté ; <strong>seul examen visualisant <span class=\"kw-clinique\">les</span> 3 temps de la déglutition</strong>. Inconvénients : coopération du patient requise, position allongée uniquement, examen irradiant</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Panendoscopie ORL</span></td><td>Tube rigide sous <span class=\"kw-clinique\">anesthésie générale</span> ; examine le pharynx et la bouche œsophagienne — indispensable au bilan d'un <span class=\"kw-etio\">carcinome des VADS</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM cervico-thoracique</span></td><td><strong>Systématique en cas de paralysie laryngée</strong> : recherche une <span class=\"kw-etio\">compression du nerf vague (X)</span> ; recherche aussi une compression extrinsèque</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IRM du tronc cérébral</span></td><td>Devant une <span class=\"kw-clinique\">dysphagie</span> sans preuve étiologique : recherche une <span class=\"kw-etio\">atteinte du tronc cérébral</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"273-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","contenu":"<p><span class=\"kw-clinique\">Les</span> étiologies de <span class=\"kw-clinique\">dysphagie</span> œsophagienne se répartissent en deux grands cadres, opposés par leur sémiologie et leur démarche.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dysphagie</span> lésionnelle</h4>\n      <p>Évocateurs : prédominance sur <span class=\"kw-clinique\">les</span> solides, aggravation avec le temps, retentissement sur l'état général, sténose organique à l'<span class=\"kw-imagerie\">endoscopie</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Tumorale</span></td><td><span class=\"kw-etio\">Cancer de l'œsophage</span> (<span class=\"kw-clinique\">carcinome</span> épidermoïde, adénocarcinome) : <span class=\"kw-clinique\">lésion</span> ulcéro-bourgeonnante, irrégulière, saignant au <span class=\"kw-def\">contact</span>, <span class=\"kw-alerte\">sténose excentrée</span></td></tr>\n          <tr><td>Compression extrinsèque</td><td><span class=\"kw-etio\">Carcinome bronchopulmonaire</span> ; <span class=\"kw-etio\">tumeurs ou adénopathies médiastinales</span></td></tr>\n          <tr><td>Sténoses non tumorales</td><td>Fibreuses, régulières, centrées : <span class=\"kw-etio\">œsophagite à éosinophiles</span> ; sténose <span class=\"kw-etio\">peptique</span> ; <span class=\"kw-etio\">caustique</span> ; <span class=\"kw-etio\">post-radique</span> ; <span class=\"kw-etio\">cicatricielle</span> ; <span class=\"kw-etio\">anastomotique post-œsophagectomie</span> ; <span class=\"kw-etio\">anneau de Schatzki</span> ; <span class=\"kw-etio\">syndrome de Plummer-Vinson</span> ; <span class=\"kw-etio\">tumeurs sous-muqueuses bénignes</span></td></tr>\n          <tr><td>Œsophagites sans sténose</td><td>Symptôme prédominant = <span class=\"kw-clinique\">odynophagie</span> : <span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-ttt\">biphosphonates</span> ; <span class=\"kw-ttt\">tétracyclines</span> ; <span class=\"kw-ttt\">chlorure de potassium</span> ; <span class=\"kw-etio\">Candida</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">HSV</span> chez l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dysphagie</span> non lésionnelle</h4>\n      <p>Évocateurs : <span class=\"kw-clinique\">dysphagie</span> fluctuant dans le temps, retentissement inconstant sur l'état général, <span class=\"kw-imagerie\">endoscopie</span> souvent normale ; quantification par le <span class=\"kw-def\">score d'Eckardt</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Troubles moteurs primaires</td><td><span class=\"kw-etio\">Achalasie</span> (absence de péristaltisme + défaut de relaxation du SIO) ; <span class=\"kw-etio\">spasmes œsophagiens</span> ; <span class=\"kw-etio\">œsophage hypercontractile « marteau-piqueur »</span> ; <span class=\"kw-etio\">péristaltisme inefficace ou absent</span></td></tr>\n          <tr><td>Troubles moteurs secondaires</td><td><span class=\"kw-etio\">Sclérodermie</span> ; <span class=\"kw-etio\">dermatomyosite</span> ; <span class=\"kw-etio\">lupus</span> ; <span class=\"kw-etio\">syndrome de Gougerot-Sjögren</span> ; myopathie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dysphagie</span> fonctionnelle</td><td>Diagnostic d'élimination, après bilan négatif</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Repère sémiologique</strong> — une <span class=\"kw-clinique\">dysphagie</span> aux <span class=\"kw-alerte\">solides</span>, d'<span class=\"kw-alerte\">aggravation progressive</span>, avec <span class=\"kw-alerte\">retentissement sur l'état général</span> = lésionnelle jusqu'à preuve du contraire. Une dysphagie <span class=\"kw-clinique\">capricieuse</span>, <span class=\"kw-clinique\">paradoxale</span> (sur <span class=\"kw-clinique\">les</span> liquides) et fluctuante oriente vers un trouble moteur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 305 — Tumeur de l'œsophage · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":0},{"id":"273-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales étiologies d’une dysphagie d’origine pharyngolaryngée et en apprécier la gravité","contenu":"<p>La <span class=\"kw-clinique\">dysphagie</span> d'origine pharyngo-laryngée (oropharyngée) relève de causes ORL et neurologiques. L'appréciation de sa gravité est essentielle : elle expose à des complications respiratoires et nutritionnelles.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Causes tumorales</td><td><span class=\"kw-etio\">Cancer du pharynx</span>, du <span class=\"kw-etio\">larynx</span>, du <span class=\"kw-etio\">1/3 supérieur de l'œsophage</span> ; <span class=\"kw-etio\">cancer de la cavité buccale</span> (<span class=\"kw-clinique\">dysphagie</span> alors tardive)</td></tr>\n          <tr><td>Causes extrinsèques</td><td><span class=\"kw-etio\">Volumineux goitre thyroïdien plongeant</span> ; <span class=\"kw-etio\">anévrisme de l'aorte thoracique</span> ; <span class=\"kw-etio\">tumeurs du médiastin</span> ; <span class=\"kw-etio\">anomalie vertébrale</span> — la <span class=\"kw-imagerie\">TDM</span> thoracique injectée précise l'extension</td></tr>\n          <tr><td>Atteinte du SSO</td><td><span class=\"kw-etio\">Diverticule de Zenker</span> ; <span class=\"kw-etio\">achalasie du sphincter supérieur</span> (hypertonie du crico-pharyngien) ; <span class=\"kw-etio\">syndrome de Plummer-Vinson</span> ; <span class=\"kw-etio\">séquelles d'ingestion de caustique</span></td></tr>\n          <tr><td>Causes neurologiques</td><td>Maladies neurodégénératives (<span class=\"kw-etio\">Parkinson</span>, <span class=\"kw-etio\">Alzheimer</span>, démence sénile) ; <span class=\"kw-etio\">myasthénie</span> ; <span class=\"kw-etio\">AVC</span> ; <span class=\"kw-etio\">SLA</span> ; <span class=\"kw-etio\">paralysie unilatérale du nerf vague</span> ; <span class=\"kw-etio\">myopathie</span> ; <span class=\"kw-etio\">syndrome pseudobulbaire</span> d'origine vasculaire</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Appréciation de la gravité</h4>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Signes de gravité</span> 🚩</strong> — <span class=\"kw-alerte\">fausses routes</span> alimentaires ou salivaires ; <span class=\"kw-alerte\">pneumopathies d'inhalation à répétition</span> ; <span class=\"kw-alerte\">dénutrition</span> ; <span class=\"kw-alerte\">déshydratation</span> ; <span class=\"kw-alerte\">otalgie réflexe</span> (<span class=\"kw-alerte\">drapeau rouge</span> devant faire rechercher un cancer).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS · 98 — Myasthénie · 106 — Parkinson</em></p>","frequence":0},{"id":"273-8","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie typique d’un corps étranger pharyngo-œsophagien","contenu":"<p>Devant la suspicion d'un <span class=\"kw-etio\">corps étranger pharyngo-œsophagien</span>, l'examen de débrouillage est une <span class=\"kw-imagerie\">radiographie simple sans opacification</span>, réalisée de <strong>face et de profil</strong>. Le corps étranger se situe en règle générale dans l'œsophage cervical, en regard du <span class=\"kw-clinique\">sphincter supérieur de l'œsophage (SSO)</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Aspect radiographique typique</h4>\n      <ul>\n        <li><strong>Corps étranger radio-opaque :</strong> situé au niveau cervical ou déjà en aval ; de profil, il se projette <span class=\"kw-radio\">en arrière de la trachée, en position prérachidienne</span>.</li>\n        <li><strong>Pile bouton</strong> (corps étranger dangereux) : aspect caractéristique en <span class=\"kw-radio\">doubles contours</span> sur la <span class=\"kw-imagerie\">radiographie</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes radiographiques de complication</h4>\n      <p>Une perforation avec médiastinite se traduit par :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Épanchement gazeux</span></li>\n        <li><span class=\"kw-radio\">Épaississement des parties molles cervico-médiastinales</span></li>\n        <li><span class=\"kw-radio\">Signe de Minigerode</span> : image claire pré-vertébrale sur la <span class=\"kw-imagerie\">radiographie</span> de profil</li>\n        <li><span class=\"kw-radio\">Emphysème médiastinal</span> sous forme d'une ligne bordante de la silhouette cardiaque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pile bouton — <span class=\"kw-alerte\">urgence</span> 🚩</strong> — risque de <span class=\"kw-alerte\">corrosion chimique</span> conduisant à une <span class=\"kw-alerte\">perforation par nécrose</span> (médiastinite, <span class=\"kw-alerte\">hémorragie massive</span> par <span class=\"kw-clinique\">lésion</span> vasculaire). L'aspect en doubles contours et l'interrogatoire orientent le diagnostic ; extraction en urgence.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/273/rp-corps-etranger-pharyngo-oesophagien.png\" alt=\"Radiographie de thorax de face montrant une formation radio-opaque enclavée dans le tiers supérieur de l'œsophage, avec aspect de double contour correspondant à une pile bouton et bords rognés évoquant une érosion\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span> — <span class=\"kw-etio\">corps étranger pharyngo-œsophagien</span>. Formation <span class=\"kw-radio\">radio-opaque enclavée dans le tiers supérieur de l'œsophage</span> ; l'<span class=\"kw-radio\">aspect de double contour</span> correspond à une <span class=\"kw-alerte\">pile bouton</span>, et l'<span class=\"kw-radio\">aspect rogné des bords</span> évoque une <span class=\"kw-clinique\">érosion</span> devant faire rechercher en urgence une <span class=\"kw-alerte\">œsophagite caustique</span>. Indication à une <span class=\"kw-clinique\">fibroscopie en urgence</span> (recommandations HAS 2022). Source : banque imagerie « Imagerie à connaître » (item 273).</figcaption>\n      </figure>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/esophageal-foreign-bodies","label":"Radiopaedia : Esophageal foreign bodies"},{"href":"https://radiopaedia.org/articles/zenker-diverticulum-1","label":"Radiopaedia : Zenker diverticulum 1"},{"href":"https://radiopaedia.org/articles/achalasia","label":"Radiopaedia : Achalasia"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré</strong></p><ul><li><span class=\"kw-alerte\">toute dysphagie = lésionnelle (cancer œsophage) jusqu'à preuve du contraire</span> → exploration <strong>non différable</strong></li></ul><p><strong><span class=\"kw-clinique\">Dysphagie</span> chronique</strong></p><p><span class=\"kw-imagerie\">EOGD</span> semi-urgente (<span class=\"kw-chiffre\">≤ 2 semaines</span> si suspicion <span class=\"kw-etio\">tumorale</span> ou <span class=\"kw-clinique\">AEG</span>)</p><p><strong>Corps étranger pharyngo-œsophagien</strong></p><p>extraction <span class=\"kw-alerte\">en urgence</span> par <span class=\"kw-imagerie\">endoscopie</span> sous AG (tube rigide)</p><p><strong>Pile bouton</strong></p><p>extraction <strong>immédiate</strong></p><ul><li><span class=\"kw-alerte\">urgence absolue</span></li><li>risque de <span class=\"kw-alerte\">corrosion chimique</span> et de <span class=\"kw-alerte\">perforation par nécrose</span></li></ul><p><strong>Ingestion caustique</strong></p><ul><li><span class=\"kw-imagerie\">TDM</span> entre <span class=\"kw-chiffre\">3-6 h</span> post-ingestion</li><li><span class=\"kw-ci\">pas de SNG, pas de lavage, pas de vomissements, pas de boisson/lait/charbon</span></li></ul><p><strong>Fausses routes massives + <span class=\"kw-alerte\">détresse</span> respiratoire</strong></p><p>protection des voies aériennes</p><ul><li><span class=\"kw-alerte\">urgence vitale</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">dysphagie</span> chronique sans <span class=\"kw-alerte\">signe de gravité</span> → consultation <span class=\"kw-def\">gastro-entérologue</span> pour <span class=\"kw-imagerie\">EOGD</span> programmée.<br><strong>Avis spécialisé associé :</strong> <span class=\"kw-def\">ORL</span> si dysphagie oropharyngée ; <span class=\"kw-def\">neurologue</span> si signes neuro (Parkinson, <span class=\"kw-alerte\">AVC</span>, myasthénie, SLA) ; <span class=\"kw-def\">oncologue</span> si tumeur retrouvée.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-alerte\">suspicion tumorale</span>, <span class=\"kw-alerte\">dénutrition</span>/<span class=\"kw-alerte\">déshydratation</span> sévère, dysphagie aiguë inexpliquée, <span class=\"kw-etio\">diverticule de Zenker</span> symptomatique avec retentissement.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">caustique grade 3</span> (<span class=\"kw-clinique\">nécrose</span> transmurale), <span class=\"kw-alerte\">médiastinite</span> sur perforation, <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-alerte\">détresse respiratoire</span> sur fausses routes massives.<br><strong>Bloc opératoire :</strong> extraction CE œsophagien sous AG par tube rigide ; abord cervical gauche + <span class=\"kw-ttt\">drainage</span> si médiastinite.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Fausses routes</span> alimentaires ou salivaires (silencieuses ou patentes)</li><li><span class=\"kw-alerte\">Pneumopathies d'inhalation à répétition</span> ± <span class=\"kw-clinique\">fièvre récurrente inexpliquée</span></li><li><span class=\"kw-alerte\">AEG</span> · <span class=\"kw-alerte\">perte de poids</span> · <span class=\"kw-alerte\">dénutrition</span> · <span class=\"kw-alerte\">déshydratation</span></li><li><span class=\"kw-alerte\">Otalgie réflexe</span> → rechercher un <span class=\"kw-etio\">cancer du pharynx</span> ou du <span class=\"kw-etio\">vestibule laryngé</span></li><li><span class=\"kw-alerte\">Stase salivaire</span> = très bon signe d'<strong>organicité</strong> (baisse propulsion pharyngée ou trouble relaxation SSO)</li><li><span class=\"kw-clinique\">Dysphagie douloureuse (odynophagie)</span> + <span class=\"kw-alerte\">AEG</span> → suspecter <span class=\"kw-etio\">cancer œsophage</span> ou <span class=\"kw-etio\">œsophagite sévère</span></li><li><span class=\"kw-clinique\">Dysphonie</span> et/ou <span class=\"kw-clinique\">dyspnée</span> → <span class=\"kw-alerte\">paralysie laryngée</span> (compression du <span class=\"kw-def\">X</span>) ou obstacle laryngo-trachéal</li><li><span class=\"kw-clinique\">Régurgitations nasales</span>, <span class=\"kw-clinique\">toux aux repas</span>, <span class=\"kw-clinique\">voix gargouillante/humide</span> = défaut de protection des voies respiratoires</li><li>Aggravation <span class=\"kw-alerte\">croissante</span> avec prédominance sur <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">solides</span> → <span class=\"kw-etio\">tumoral</span> jusqu'à preuve du contraire</li><li>Corps étranger : <span class=\"kw-alerte\">pile bouton</span> (aspect en <span class=\"kw-radio\">doubles contours</span>) — perforation imminente par corrosion</li><li>Médiastinite sur perforation : <span class=\"kw-alerte\">douleur</span> + <span class=\"kw-alerte\">empâtement cervical</span> + <span class=\"kw-alerte\">emphysème sous-cutané</span> + <span class=\"kw-clinique\">fièvre</span> ± <span class=\"kw-radio\">signe de Minigerode</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">dysphagie</span> est <span class=\"kw-alerte\">lésionnelle jusqu'à preuve du contraire</span> → <span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies</span> systématiques, <strong>même si muqueuse macroscopiquement normale</strong> (recherche d'<span class=\"kw-etio\">œsophagite à éosinophiles</span>).</p><ul><li><strong>Bilan systématique en <span class=\"kw-chiffre\">1ère intention</span> :</strong> <span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies œsophagiennes</span> étagées, quel que soit le type de <span class=\"kw-clinique\">dysphagie</span></li><li><strong><span class=\"kw-clinique\">Dysphagie</span> oropharyngée :</strong> bilan <span class=\"kw-def\">ORL</span> (nasofibroscopie de déglutition, <span class=\"kw-imagerie\">vidéo-fluoroscopie</span> = gold standard, <span class=\"kw-imagerie\">panendoscopie ORL</span> si suspicion VADS) + bilan <span class=\"kw-def\">neurologique</span> (<span class=\"kw-imagerie\">IRM tronc cérébral</span> si pas d'étiologie)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne avec <span class=\"kw-clinique\">lésion</span> :</strong> traitement étiologique selon la cause (oncologique, <span class=\"kw-ttt\">dilatation endoscopique</span> pour sténoses bénignes, <span class=\"kw-ttt\">IPP</span> pour œsophagite peptique)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne sans <span class=\"kw-clinique\">lésion</span>, biopsies positives :</strong> <span class=\"kw-etio\">œsophagite à éosinophiles</span> → <span class=\"kw-ttt\">corticothérapie locale</span> (<span class=\"kw-ttt\">corticoïdes</span> inhalés à avaler)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne sans <span class=\"kw-clinique\">lésion</span>, biopsies négatives :</strong> <span class=\"kw-imagerie\">manométrie œsophagienne</span> en ambulatoire (péristaltisme + relaxation SIO)</li><li><span class=\"kw-etio\">Achalasie</span> confirmée → <span class=\"kw-ttt\">dilatation pneumatique du SIO</span>, <span class=\"kw-ttt\">myotomie de Heller</span> ou <span class=\"kw-ttt\">POEM</span> ; <span class=\"kw-ttt\">toxine botulique</span> si CI chirurgicale ; <span class=\"kw-ttt\">inhibiteurs calciques</span> en symptomatique</li><li><span class=\"kw-etio\">Diverticule de Zenker</span> symptomatique → <span class=\"kw-ttt\">myotomie extramuqueuse</span> (voie ouverte) ou <span class=\"kw-ttt\">myotomie transmuqueuse</span> (voie endoscopique)</li><li><span class=\"kw-etio\">Corps étranger œsophagien</span> reconnu → <span class=\"kw-ttt\">extraction sous AG</span> par voie endoscopique avec tubes rigides ; <span class=\"kw-ttt\">abord cervical gauche</span> + <span class=\"kw-ttt\">drainage</span> si médiastinite</li><li><strong>Renutrition / hydratation</strong> parallèles dès qu'il y a retentissement (<span class=\"kw-ttt\">SNG</span>, <span class=\"kw-ttt\">complémentation orale</span>, voire <span class=\"kw-ttt\">gastrostomie</span> si <span class=\"kw-clinique\">dysphagie</span> chronique sévère)</li><li><strong>Caustiques :</strong> <span class=\"kw-ci\">pas de SNG / lavage gastrique / vomissements induits</span> ; <span class=\"kw-ci\">pas de boisson, lait, charbon activé</span> ; position proclive 45° + réa + <span class=\"kw-imagerie\">TDM 3-6 h</span> + <span class=\"kw-def\">classification</span> radiologique grades 1-2-3 conditionnant la suite</li></ul>","suivi":"<p><strong>Nutritionnel :</strong> <span class=\"kw-clinique\">poids</span>, <span class=\"kw-bio\">albumine</span>, <span class=\"kw-bio\">préalbumine</span>, <span class=\"kw-clinique\">IMC</span> ; consultation <span class=\"kw-def\">diététicienne</span> ; adaptation des textures si <span class=\"kw-clinique\">dysphagie</span> oropharyngée chronique.<br><strong>Orthophonie :</strong> rééducation déglutition (post-AVC, Parkinson, troubles oropharyngés chroniques).<br><strong><span class=\"kw-imagerie\">EOGD</span> de contrôle :</strong> selon étiologie — <span class=\"kw-etio\">œsophagite peptique</span> (recherche endobrachyœsophage à <span class=\"kw-chiffre\">2 mois</span> de traitement), <span class=\"kw-etio\">œsophagite à éosinophiles</span> (réponse à <span class=\"kw-ttt\">corticothérapie</span>), <span class=\"kw-etio\">cancer œsophage</span> (bilan & <span class=\"kw-def\">suivi</span> onco), <span class=\"kw-etio\">sténose caustique</span> (Zargar endoscopique au décours).<br><strong>Prévention <span class=\"kw-clinique\">pneumopathie d'inhalation</span> :</strong> <span class=\"kw-ttt\">vaccin antipneumococcique</span> + <span class=\"kw-ttt\">antigrippal</span> ; hygiène buccale ; positionnement aux repas.<br><strong>Après détorsion <span class=\"kw-etio\">diverticule de Zenker</span> ou <span class=\"kw-etio\">achalasie</span> traitée :</strong> <span class=\"kw-def\">surveillance</span> clinique du <span class=\"kw-def\">score d'Eckardt</span> (dysphagie, régurgitations, douleur, perte de poids) à distance.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/esophageal-foreign-bodies","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/zenker-diverticulum-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/achalasia","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dysphagie confirmée à l'interrogatoire — Préalable : éliminer odynophagie, globus, anorexie, satiété précoce, rumination","detail":"<h4>Démarche diagnostique — <span class=\"kw-clinique\">Dysphagie</span> — Siège → <span class=\"kw-imagerie\">EOGD</span> systématique → mécanisme → étiologie</h4>","branches":[{"to":"q-oropharyngee","label":"Siège cervical / fausses routes / voix gargouillante","color":"amber"},{"to":"q-eogd","label":"Siège rétrosternal / blocage après déglutition","color":"blue"}]},{"id":"q-oropharyngee","kind":"decision","label":"Dysphagie OROPHARYNGÉE — Causes ORL ou neurologiques · Bilan : ORL complet + neuro + nasofibroscopie + vidéo-fluoroscopie","branches":[{"to":"t-vads","label":"Otalgie réflexe / AEG / tabac-alcool","color":"red"},{"to":"t-neuro","label":"Syndrome neurologique (AVC, Parkinson, SLA, myasthénie)","color":"amber"},{"to":"t-zenker","label":"Ruminations + régurgitations + bruits hydro-aériques","color":"amber"},{"to":"t-sso","label":"Sténose du SSO / Plummer-Vinson / séquelles caustiques","color":"amber"}]},{"id":"t-vads","kind":"terminal","label":"Cancer des VADS","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie oropharyngée</span> + <span class=\"kw-alerte\">otalgie réflexe</span> (<span class=\"kw-alerte\">drapeau rouge</span>)</li><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">perte de poids</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">intoxication alcoolo-tabagique</span></li><li>Localisations : <span class=\"kw-etio\">cancer du pharynx</span>, <span class=\"kw-etio\">larynx</span>, <span class=\"kw-etio\">1/3 supérieur de l'œsophage</span>, <span class=\"kw-etio\">cavité buccale</span> (<span class=\"kw-clinique\">dysphagie</span> tardive)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Panendoscopie ORL</span> sous AG (indispensable pour le bilan)</li><li><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span> (extension + recherche compression du X)</li><li><span class=\"kw-bio\">Biopsies</span> sous AG</li><li><span class=\"kw-def\">Bilan d'extension</span> carcinologique standard</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> / <span class=\"kw-ttt\">radiothérapie</span> / chimiothérapie selon <span class=\"kw-def\">stade</span>, en <span class=\"kw-def\">RCP</span> oncologique.</li></ul><h4>Renvoi</h4><ul><li>Cf. item <strong>298</strong> — Tumeur cavité buccale-nasosinusienne-cavum-VADS.</li></ul>"},{"id":"t-neuro","kind":"terminal","label":"Cause neurologique","color":"amber","detail":"<h4>Étiologies</h4><ul><li>Maladies neurodégénératives : <span class=\"kw-etio\">Parkinson</span>, <span class=\"kw-etio\">Alzheimer</span>, démence sénile</li><li><span class=\"kw-etio\">AVC</span> (notamment du tronc cérébral)</li><li><span class=\"kw-etio\">SLA</span>, <span class=\"kw-etio\">myasthénie</span>, <span class=\"kw-etio\">myopathie</span></li><li><span class=\"kw-etio\">Paralysie unilatérale du nerf vague (X)</span></li><li><span class=\"kw-etio\">Syndrome pseudobulbaire</span> d'origine vasculaire</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM du tronc cérébral</span> devant <span class=\"kw-clinique\">dysphagie</span> sans étiologie</li><li><span class=\"kw-imagerie\">TDM cervico-thoracique</span> systématique si <span class=\"kw-alerte\">paralysie laryngée</span> (compression du <span class=\"kw-def\">X</span>)</li><li>Bilan neurologique adapté (<span class=\"kw-bio\">EMG</span>, recherche <span class=\"kw-bio\">anticorps anti-récepteurs</span> acétylcholine si myasthénie)</li></ul><h4>Conduite</h4><ul><li>Traitement étiologique de la maladie neurologique</li><li><span class=\"kw-ttt\">Orthophonie</span> : rééducation de la déglutition</li><li>Adaptation des textures (épaississants, eau gélifiée)</li><li><span class=\"kw-ttt\">Gastrostomie</span> si <span class=\"kw-clinique\">dysphagie</span> sévère chronique avec retentissement</li></ul><h4>Renvois</h4><ul><li>Cf. items <strong>98</strong> (Myasthénie), <strong>106</strong> (Parkinson).</li></ul>"},{"id":"t-zenker","kind":"terminal","label":"Diverticule de Zenker","color":"amber","detail":"<h4>Définition</h4><ul><li>Hernie de la face postérieure de la jonction pharyngo-laryngée, <strong>au-dessus du SSO</strong>, se développant vers le médiastin rétro-œsophagien.</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie haute</span></li><li><span class=\"kw-clinique\">Ruminations</span>, <span class=\"kw-clinique\">régurgitations d'aliments non digérés</span> (parfois déclenchées par pression cervicale)</li><li><span class=\"kw-clinique\">Bruits hydro-aériques</span></li><li><span class=\"kw-clinique\">Toux nocturne</span> de décubitus</li><li>Retentissement : <span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">pneumopathie d'inhalation</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Nasofibroscopie</span> : <strong>signe de la marée pathognomonique</strong> (bouchée disparaît puis réapparaît)</li><li><span class=\"kw-imagerie\">Radio-cinéma de la déglutition</span> : confirme le diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Myotomie extramuqueuse</span> (voie ouverte)</li><li>OU <span class=\"kw-ttt\">myotomie transmuqueuse</span> (voie endoscopique)</li></ul>"},{"id":"t-sso","kind":"terminal","label":"Atteinte du SSO","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Achalasie du sphincter supérieur</span> (hypertonie du crico-pharyngien)</li><li><span class=\"kw-etio\">Syndrome de Plummer-Vinson</span> (ou Kelly-Patterson)</li><li><span class=\"kw-etio\">Séquelles d'ingestion de caustique</span></li><li><span class=\"kw-etio\">Compression extrinsèque</span> : volumineux goitre plongeant, anévrisme aorte thoracique, tumeur médiastin, anomalie vertébrale</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM thoracique injectée</span> pour préciser une compression extrinsèque</li><li><span class=\"kw-imagerie\">Manométrie</span> peu performante pour l'étude du SSO</li></ul><h4>Traitement</h4><ul><li>Selon étiologie — <span class=\"kw-ttt\">chirurgie</span> de la cause extrinsèque, <span class=\"kw-ttt\">dilatation</span> ou <span class=\"kw-ttt\">myotomie</span> du crico-pharyngien.</li></ul>"},{"id":"q-eogd","kind":"decision","label":"Dysphagie ŒSOPHAGIENNE → EOGD + biopsies SYSTÉMATIQUES — Biopsies même si muqueuse macroscopiquement normale (œsophagite à éosinophiles)","branches":[{"to":"q-lesion","label":"Lésion macroscopique visible","color":"red"},{"to":"q-biopsies","label":"EOGD macroscopiquement normale","color":"blue"}]},{"id":"q-lesion","kind":"decision","label":"Dysphagie LÉSIONNELLE — Caractériser la lésion","branches":[{"to":"t-cancer-oeso","label":"Ulcéro-bourgeonnante, irrégulière, sténose excentrée","color":"red"},{"to":"t-stenose-benigne","label":"Sténose fibreuse régulière centrée (peptique, caustique, post-radique, Schatzki)","color":"amber"},{"to":"t-oesophagite-medic","label":"Œsophagite sans sténose (médicaments, infections, RGO)","color":"amber"},{"to":"t-compression","label":"Compression extrinsèque (tumeur médiastinale, adénopathies)","color":"red"}]},{"id":"t-cancer-oeso","kind":"terminal","label":"Cancer de l'œsophage","color":"red","detail":"<h4>Aspect <span class=\"kw-imagerie\">EOGD</span></h4><ul><li><span class=\"kw-clinique\">Lésion</span> <strong>ulcéro-bourgeonnante</strong>, <strong>irrégulière</strong></li><li><span class=\"kw-alerte\">Saigne au contact</span></li><li><span class=\"kw-alerte\">Sténose excentrée</span></li><li>Types : <span class=\"kw-etio\">carcinome épidermoïde</span> (<span class=\"kw-etio\">alcool</span>-tabac) · <span class=\"kw-etio\">adénocarcinome</span> (endobrachyœsophage)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> aux <span class=\"kw-alerte\">solides</span>, d'<span class=\"kw-alerte\">aggravation progressive</span></li><li><span class=\"kw-alerte\">Retentissement sur l'état général</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">intoxication alcoolo-tabagique</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Biopsies multiples étagées</span></li><li><span class=\"kw-imagerie\">Écho-endoscopie haute</span> (bilan local)</li><li><span class=\"kw-imagerie\">TDM-TAP injectée</span> (extension)</li><li>Discussion en <span class=\"kw-def\">RCP</span></li></ul><h4>Renvoi</h4><ul><li>Cf. item <strong>305</strong> — Tumeur de l'œsophage.</li></ul>"},{"id":"t-stenose-benigne","kind":"terminal","label":"Sténose bénigne (non tumorale)","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sténose peptique</span> (<span class=\"kw-clinique\">RGO</span> chronique → cf item <strong>271</strong>)</li><li><span class=\"kw-etio\">Sténose caustique</span> (séquelle d'ingestion)</li><li><span class=\"kw-etio\">Sténose post-radique</span></li><li><span class=\"kw-etio\">Sténose cicatricielle</span> ou <span class=\"kw-etio\">anastomotique post-œsophagectomie</span></li><li><span class=\"kw-etio\">Anneau de Schatzki</span> (diaphragme du 1/3 inférieur)</li></ul><h4>Aspect <span class=\"kw-imagerie\">EOGD</span></h4><ul><li>Sténose <strong>fibreuse</strong>, <strong>régulière</strong>, <strong>centrée</strong> (contraste avec la sténose excentrée <span class=\"kw-etio\">tumorale</span>).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dilatation endoscopique</span> (bougies, ballonnets)</li><li><span class=\"kw-ttt\">IPP au long cours</span> si sténose peptique</li><li>Traitement étiologique selon la cause</li><li><span class=\"kw-bio\">Biopsies</span> pour éliminer une néoplasie sous-jacente</li></ul>"},{"id":"t-oesophagite-medic","kind":"terminal","label":"Œsophagite (sans sténose)","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Médicamenteuse</span> : <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">biphosphonates</span>, <span class=\"kw-ttt\">tétracyclines</span>, <span class=\"kw-ttt\">chlorure de potassium</span></li><li><span class=\"kw-etio\">Infectieuse</span> chez l'immunodéprimé : <span class=\"kw-etio\">Candida</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">HSV</span></li><li><span class=\"kw-etio\">Peptique</span> (<span class=\"kw-clinique\">RGO</span> chronique → cf item <strong>271</strong>)</li></ul><h4>Symptôme prédominant</h4><ul><li><span class=\"kw-clinique\">Odynophagie</span> (déglutition douloureuse), parfois <span class=\"kw-clinique\">dysphagie</span> associée.</li></ul><h4>Traitement</h4><ul><li>Arrêt du médicament en cause + conseils de prise (debout, grand verre d'eau)</li><li><span class=\"kw-ttt\">IPP</span> si œsophagite peptique</li><li><span class=\"kw-ttt\">Antifongique</span> (<span class=\"kw-ttt\">fluconazole</span>) / <span class=\"kw-ttt\">antiviral</span> si cause infectieuse</li></ul>"},{"id":"t-compression","kind":"terminal","label":"Compression extrinsèque","color":"red","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Carcinome bronchopulmonaire</span></li><li><span class=\"kw-etio\">Tumeurs ou adénopathies médiastinales</span></li><li><span class=\"kw-etio\">Volumineuse hernie hiatale par roulement</span></li><li><span class=\"kw-etio\">Diverticule œsophagien</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM-TAP injectée</span> avec opacification digestive haute (examen clé)</li><li><span class=\"kw-imagerie\">Écho-endoscopie haute</span> si suspicion de <span class=\"kw-etio\">tumeur sous-muqueuse</span> (caractérisation + <span class=\"kw-ttt\">ponction</span>)</li></ul><h4>Traitement</h4><ul><li>Étiologique — chirurgical / oncologique selon la cause comprimante.</li></ul>"},{"id":"q-biopsies","kind":"decision","label":"Résultat des biopsies œsophagiennes ? — Biopsies systématiques — clé du diagnostic","branches":[{"to":"t-eosino","label":"Infiltrat à PNE (> 15/champ x400)","color":"green"},{"to":"q-manometrie","label":"Biopsies normales → manométrie œsophagienne","color":"blue"}]},{"id":"t-eosino","kind":"terminal","label":"Œsophagite à éosinophiles","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Enfant ou sujet jeune, prédominance <strong>masculine</strong></li><li><span class=\"kw-etio\">Terrain atopique</span> (asthme, <span class=\"kw-clinique\">eczéma</span>) dans <span class=\"kw-chiffre\">50-80 %</span> des cas</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> avec <span class=\"kw-clinique\">sensation de blocage alimentaire</span>, parfois <strong>intermittente</strong>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie sanguine</span> possible</li><li><span class=\"kw-imagerie\">EOGD</span> : <strong>souvent normale</strong>, parfois anomalies (<span class=\"kw-radio\">dépôts granités blanchâtres</span>, <span class=\"kw-radio\">stries linéaires verticales</span>, <span class=\"kw-radio\">aspect pseudo-trachéal</span>)</li><li><span class=\"kw-bio\">Histologie</span> : <strong>infiltrat à PNE <span class=\"kw-chiffre\">> 15</span>/champ au grossissement x 400</strong> = diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie locale</span> (<span class=\"kw-ttt\">corticoïdes</span> inhalés à <strong>avaler</strong>)</li><li>Réponse clinique et histologique évaluée à <span class=\"kw-chiffre\">8-12 semaines</span></li><li>Pas de risque de cancer ; risque de <span class=\"kw-alerte\">sténose</span> et <span class=\"kw-alerte\">perforation</span> en cas d'<span class=\"kw-clinique\">évolution</span></li></ul>"},{"id":"q-manometrie","kind":"decision","label":"Manométrie œsophagienne en 2ᵉ intention — Évalue péristaltisme + relaxation du SIO en ambulatoire","branches":[{"to":"t-achalasie","label":"Absence péristaltisme + défaut relaxation SIO","color":"amber"},{"to":"t-trouble-moteur","label":"Autre trouble moteur primaire (spasmes, marteau-piqueur)","color":"amber"},{"to":"t-trouble-secondaire","label":"Trouble moteur secondaire (sclérodermie, lupus, Gougerot)","color":"amber"},{"to":"t-fonctionnelle","label":"Manométrie normale","color":"green"}]},{"id":"t-achalasie","kind":"terminal","label":"Achalasie","color":"amber","detail":"<h4>Définition</h4><ul><li>Trouble moteur <strong>primitif</strong> de l'œsophage de cause inconnue : <span class=\"kw-alerte\">absence de relaxation du SIO</span> + <span class=\"kw-alerte\">absence de péristaltisme</span> dans le corps.</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie paradoxale</span> (prédomine sur <span class=\"kw-clinique\">les</span> <strong>liquides</strong>), <span class=\"kw-clinique\">capricieuse</span>, intermittente</li><li><span class=\"kw-clinique\">Régurgitations</span> notamment en <strong>décubitus</strong></li><li><span class=\"kw-clinique\">Douleurs rétrosternales constrictives</span> pseudo-angineuses (non liées à l'effort)</li><li><span class=\"kw-alerte\">Amaigrissement</span> quantifié par le <span class=\"kw-def\">score d'Eckardt</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> : souvent normale au début, ressaut au passage du cardia ; <span class=\"kw-def\">stade</span> évolué = œsophage <span class=\"kw-radio\">dilaté, atone</span> avec résidus</li><li><span class=\"kw-imagerie\">TOGD</span> : <span class=\"kw-radio\">méga-œsophage</span>, cardia en <strong>bec d'oiseau</strong>, stase du PDC dans le 1/3 inférieur</li><li><span class=\"kw-imagerie\">Manométrie</span> : Type 1 (défaut SIO isolé) · Type 2 (pressurisation pan-œsophagienne) · Type 3 (contractions prématurées spastiques <span class=\"kw-chiffre\">≥ 20 %</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dilatation pneumatique du SIO</span> (endoscopique)</li><li><span class=\"kw-ttt\">Myotomie de Heller</span> (chirurgicale) + antireflux</li><li><span class=\"kw-ttt\">POEM</span> (Per-Oral Endoscopic Myotomy)</li><li><span class=\"kw-ttt\">Toxine botulique</span> si CI chirurgicale (effet transitoire)</li><li><span class=\"kw-ttt\">Inhibiteurs calciques</span> / <span class=\"kw-ttt\">dérivés nitrés</span> en symptomatique</li></ul><h4><span class=\"kw-def\">Diagnostic différentiel</span></h4><ul><li><span class=\"kw-etio\">Adénocarcinome du cardia</span> (<span class=\"kw-clinique\">achalasie</span> <strong>secondaire</strong>) → toujours faire <span class=\"kw-imagerie\">EOGD</span> + biopsies</li><li><span class=\"kw-etio\">Maladie de Chagas</span> (Trypanosoma cruzi, Amérique du Sud)</li></ul>"},{"id":"t-trouble-moteur","kind":"terminal","label":"Autre trouble moteur œsophagien primaire","color":"amber","detail":"<h4>Entités</h4><ul><li><span class=\"kw-etio\">Spasmes œsophagiens</span> (contractions simultanées non péristaltiques)</li><li><span class=\"kw-etio\">Œsophage hypercontractile</span> ou « marteau-piqueur » (jackhammer)</li><li><span class=\"kw-etio\">Péristaltisme œsophagien inefficace ou absent</span> (avec relaxation SIO normale)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> + douleurs rétrosternales, fluctuantes, sans aggravation progressive.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Inhibiteurs calciques</span> · <span class=\"kw-ttt\">dérivés nitrés</span></li><li><span class=\"kw-ttt\">IPP</span> (souvent associés à un <span class=\"kw-clinique\">RGO</span>)</li><li>Prise en charge symptomatique adaptée</li></ul>"},{"id":"t-trouble-secondaire","kind":"terminal","label":"Trouble moteur secondaire","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sclérodermie</span> (atteinte œsophagienne très fréquente)</li><li><span class=\"kw-etio\">Dermatomyosite</span></li><li><span class=\"kw-etio\">Lupus érythémateux disséminé</span></li><li><span class=\"kw-etio\">Syndrome de Gougerot-Sjögren</span></li><li><span class=\"kw-etio\">Myopathies</span>, <span class=\"kw-etio\">paranéoplasique</span></li></ul><h4>Conduite</h4><ul><li>Diagnostic et prise en charge de la <strong>maladie générale</strong></li><li><span class=\"kw-ttt\">IPP</span> car <span class=\"kw-clinique\">RGO</span> souvent associé (hypotonie SIO)</li><li><span class=\"kw-def\">Surveillance</span> des complications œsophagiennes</li></ul>"},{"id":"t-fonctionnelle","kind":"terminal","label":"Dysphagie fonctionnelle","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Diagnostic d'élimination</span> — bilan complet négatif (<span class=\"kw-imagerie\">EOGD</span> + biopsies + manométrie tous normaux).</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> sans support organique ni moteur, souvent fluctuante.</li></ul><h4>Conduite</h4><ul><li>Réassurance, explication</li><li>Prise en charge symptomatique (modifications alimentaires)</li><li>Consultation psychologique selon contexte</li><li><span class=\"kw-ttt\">Antidépresseurs tricycliques</span> à faible dose si gêne importante</li></ul>"}]},"cards":[{"i":"3a869bcd9ccf","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Quels sont les diagnostics différentiels principaux à écarter face à une suspicion de dysphagie, en l'absence de blocage alimentaire ?","a":"<ul><li>L'<strong>odynophagie</strong> (douleur sans obstacle)</li><li>Le <strong>globus hystericus</strong> (sensation de compression cervicale liée à l'angoisse)</li><li>L'<strong>anorexie</strong> (perte d'appétit)</li><li>La <strong>satiété précoce</strong> (faim rapidement coupée sans blocage)</li><li>Le <strong>syndrome de rumination</strong> (remontées volontaires d'aliments déjà descendus)</li></ul>"},{"i":"45b04f845e5c","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Quelle est la définition de la dysphagie ?","a":"<p>La dysphagie est définie comme une <strong>sensation de gêne ou d'obstacle à la progression du bol alimentaire</strong>, survenant au cours de la déglutition. C'est la notion de <strong>blocage du transit alimentaire</strong> qui la caractérise.</p>"},{"i":"f8edf0928366","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Comment distinguer la dysphagie de l'odynophagie ?","a":"<p>L'<strong>odynophagie</strong> est une <strong>douleur ressentie lors de la progression des aliments</strong> dans l'œsophage, mais <strong>sans sensation de blocage</strong>, à la différence de la dysphagie où il y a un obstacle. Cependant, les deux peuvent coexister (on parle alors de « dysphagie douloureuse ») suggérant une infection, une œsophagite ou une tumeur.</p>"},{"i":"4073ddd36be6","n":273,"o":"273-2","u":"Définition","t":"Connaître les deux types de dysphagie","q":"Selon le mécanisme, quels sont les deux types de dysphagie et leurs caractéristiques principales ?","a":"Il existe deux types de dysphagie selon le mécanisme :\n<ul>\n<li>La <strong>dysphagie lésionnelle</strong> : elle est liée à une <strong>lésion organique</strong> œsophagienne ou à une compression extrinsèque.</li>\n<li>La <strong>dysphagie fonctionnelle</strong> (ou non lésionnelle) : <strong>aucune lésion n'est identifiée</strong> ; elle est due à une anomalie de la dynamique propulsive du bol alimentaire.</li>\n</ul>"},{"i":"88aea8784aa8","n":273,"o":"273-2","u":"Définition","t":"Connaître les deux types de dysphagie","q":"Selon la localisation, quels sont les deux types de dysphagie et leurs caractéristiques principales ?","a":"Il existe deux types de dysphagie selon la localisation :\n<ul>\n<li>La <strong>dysphagie œsophagienne</strong> : sensation de blocage du bol alimentaire au niveau <strong>rétrosternal</strong>, après le déclenchement de la déglutition.</li>\n<li>La <strong>dysphagie oropharyngée</strong> : difficulté à initier la déglutition et à propulser le bol dans l'œsophage, gêne ressentie au niveau <strong>cervical</strong>. Les causes sont essentiellement ORL ou neurologiques.</li>\n</ul>"},{"i":"0bb941a29ae1","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels sont les signes de gravité à rechercher devant toute dysphagie ?","a":"<p>Les signes de gravité à rechercher devant toute dysphagie sont :</p><ul><li>Les <strong>infections pulmonaires</strong> ou pneumopathies à répétition, témoignant de fausses routes.</li><li>Une <strong>perte de poids</strong>.</li><li>Une <strong>dénutrition</strong>.</li><li>Une <strong>déshydratation</strong>.</li></ul><p>Toute dysphagie doit être considérée comme lésionnelle (cancer de l'œsophage) jusqu'à preuve du contraire, rendant l'<strong>endoscopie œso-gastro-duodénale avec biopsies systématique</strong>.</p>"},{"i":"4778810b1124","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels éléments de l'interrogatoire orientent vers une dysphagie non lésionnelle ou fonctionnelle ?","a":"<p>L'orientation vers une dysphagie non lésionnelle (ou fonctionnelle) est suggérée par :</p><ul><li>Une dysphagie prédominant sur les <strong>liquides</strong>.</li><li>Une dysphagie <strong>paradoxale</strong> (prédominant sur les liquides), classique de l'achalasie.</li></ul>"},{"i":"cbd41c3702c6","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels éléments de l'interrogatoire orientent vers une dysphagie lésionnelle ?","a":"<p>L'orientation vers une dysphagie lésionnelle est suggérée par :</p><ul><li>Une <strong>aggravation croissante</strong> de la dysphagie, évoquant une pathologie tumorale.</li><li>Une dysphagie prédominant sur les <strong>solides</strong>.</li><li>La présence d'une <strong>stase salivaire</strong>, signe d'organicité.</li><li>Une <strong>dysphagie douloureuse</strong> (odynophagie).</li><li>Des <strong>symptômes associés</strong> comme une dysphonie, une dyspnée (paralysie laryngée, obstacle laryngo-trachéal) ou une otalgie réflexe (cancer du pharynx/larynx).</li><li>Des <strong>antécédents</strong> d'intoxication alcoolo-tabagique.</li></ul>"},{"i":"776ad99877db","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quel est l'intérêt principal de l'EOGD en cas de dysphagie ?","a":"<p>L'EOGD permet de <strong>visualiser directement la muqueuse œsophagienne, gastrique et duodénale</strong> et d'effectuer des <strong>biopsies</strong>.</p>"},{"i":"d1e3474a012c","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quel est l'examen complémentaire non biologique de première intention à réaliser devant toute dysphagie, quel que soit son type ?","a":"<p>L'<strong>endoscopie œso-gastro-duodénale (EOGD)</strong> est l'examen clé de première intention devant toute dysphagie.</p>"},{"i":"d586e9850400","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Pourquoi des biopsies œsophagiennes sont-elles systématiques lors d'une EOGD pour dysphagie, même si la muqueuse est macroscopiquement normale ?","a":"<ul><li>Les biopsies sont indispensables pour rechercher une <strong>œsophagite à éosinophiles</strong>, une cause fréquente de dysphagie où la muqueuse peut apparaître macroscopiquement normale.</li><li>Une muqueuse d'aspect normal à l'endoscopie n'élimine donc pas cette pathologie.</li></ul>"},{"i":"ddd9fb4b901f","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quels éléments, observés lors d'une EOGD, peuvent évoquer un trouble moteur œsophagien chez un patient présentant une dysphagie ?","a":"<p>Une <strong>sensation de ressaut</strong> au passage de l'endoscope à travers la jonction œso-gastrique est évocatrice d'un trouble moteur œsophagien.</p>"},{"i":"023478f3429c","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies des dysphagies non lésionnelles ?","a":"<p>Les principales étiologies des dysphagies non lésionnelles se divisent en :</p><ul><li><strong>Troubles moteurs primaires</strong> : <strong>achalasie</strong> (absence de péristaltisme + défaut de relaxation du SIO), spasmes œsophagiens, œsophage hypercontractile « <strong>marteau-piqueur</strong> », péristaltisme inefficace ou absent.</li><li><strong>Troubles moteurs secondaires</strong> : associés à des maladies systémiques comme la <strong>sclérodermie</strong>, la dermatomyosite, le lupus, le syndrome de Gougerot-Sjögren, la myopathie.</li><li>La <strong>dysphagie fonctionnelle</strong> : il s'agit d'un diagnostic d'élimination, après un bilan négatif.</li></ul>"},{"i":"2d3a98af9207","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les causes non tumorales de sténose œsophagienne pouvant entraîner une dysphagie lésionnelle ?","a":"<p>Les causes non tumorales de sténose œsophagienne entraînant une dysphagie lésionnelle sont :</p><ul><li>Les sténoses fibreuses, régulières et centrées : <strong>œsophagite à éosinophiles</strong>, <strong>sténose peptique</strong>, <strong>caustique</strong>, <strong>post-radique</strong>, <strong>cicatricielle</strong>, <strong>anastomotique</strong> (post-œsophagectomie).</li><li>L'<strong>anneau de Schatzki</strong>.</li><li>Le <strong>syndrome de Plummer-Vinson</strong>.</li><li>Les <strong>tumeurs sous-muqueuses bénignes</strong>.</li></ul>"},{"i":"3e84bcfb7d57","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies tumorales de la dysphagie œsophagienne ?","a":"<p>Les principales étiologies tumorales de dysphagie œsophagienne sont :</p><ul><li>Le <strong>cancer de l'œsophage</strong> : il s'agit d'une lésion ulcéro-bourgeonnante, irrégulière, saignant au contact, entraînant une sténose excentrée. Il peut s'agir de <strong>carcinome épidermoïde</strong> ou d'<strong>adénocarcinome</strong>.</li><li>La <strong>compression extrinsèque</strong> par une tumeur ou une adénopathie médiastinale, telle qu'un carcinome bronchopulmonaire.</li></ul>"},{"i":"4e7ca4388a82","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies des œsophagites sans sténose responsables de dysphagie ?","a":"<p>Les principales étiologies des œsophagites sans sténose, dont le symptôme prédominant est l'<strong>odynophagie</strong>, sont :</p><ul><li>Les inflammations médicamenteuses : <strong>AINS</strong>, <strong>biphosphonates</strong>, <strong>tétracyclines</strong>, <strong>chlorure de potassium</strong>.</li><li>Les infections opportunistes chez l'immunodéprimé : <strong>Candida</strong>, <strong>CMV</strong>, <strong>HSV</strong>.</li></ul>"},{"i":"ebcf86969f20","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Comment différencier cliniquement une dysphagie lésionnelle d'une dysphagie non lésionnelle ?","a":"<p>Une dysphagie <strong>lésionnelle</strong> est généralement évoquée par :</p><ul><li>Une prédominance sur les <strong>solides</strong>.</li><li>Une <strong>aggravation progressive</strong> avec le temps.</li><li>Un <strong>retentissement sur l'état général</strong>.</li></ul><p>Une dysphagie <strong>non lésionnelle</strong> (ou fonctionnelle/trouble moteur) est évoquée par :</p><ul><li>Une dysphagie <strong>fluctuante</strong> dans le temps.</li><li>Un retentissement <strong>inconstant</strong> sur l'état général.</li><li>Une dysphagie <strong>capricieuse</strong>, voire paradoxale (sur les liquides).</li><li>Une endoscopie souvent <strong>normale</strong>.</li></ul>"}]};